-- 选中/悬停到空间传送实体时兜底注册：即使建造事件因任何原因漏登记，
-- 玩家视线扫过带子/管道的瞬间它也会进入候选列表
script.on_event(defines.events.on_selected_entity_changed, function(event)
    local player = game.players[event.player_index]
    local selected = player.selected

    if selected and selected.valid and is_portal_entity(selected) then
        ensure_storage()
        for _, portal in pairs(storage.portal_belts) do
            if portal.entity == selected then return end
        end
        register_portal_belt(selected, event.player_index)
    end
end)

-- 在玩家点击传送带时显示配对界面
script.on_event("portal-configure", function(event)
    ensure_storage()
    local player = game.players[event.player_index]
    local selected = player.selected

    -- 如果选中了传送带，显示配对界面
    if selected and selected.valid and is_portal_entity(selected) then
        -- 查找传送带ID
        local portal_id = nil
        for id, portal in pairs(storage.portal_belts) do
            if portal.entity == selected then
                portal_id = id
                break
            end
        end

        -- 如果找到ID，显示配对界面
        if portal_id then
            show_pairing_gui(event.player_index, portal_id)
        else
            -- 如果没找到ID，可能是新放置的，需要注册
            portal_id = register_portal_belt(selected, event.player_index)
            show_pairing_gui(event.player_index, portal_id)
        end
    end
end)

-- 处理GUI点击事件
script.on_event(defines.events.on_gui_click, function(event)
    ensure_storage()
    local player = game.players[event.player_index]
    local element = event.element

    if not element or not element.valid then return end

    -- 在列表中选择搭档：二次校验通过后立即配对，窗口刷新为锁定态
    if element.name == "portal_select_button" and element.tags and element.tags.portal_id then
        local player_data = storage.players[event.player_index]
        local portal_id = player_data and player_data.configuring_portal_id
        local my_portal = portal_id and storage.portal_belts[portal_id]
        local my_entity = my_portal and my_portal.entity
        local target = storage.portal_belts[element.tags.portal_id]
        local target_entity = target and target.entity

        -- 开窗后状态可能已变化（候选被别人配掉/被拆/被按 R 翻转），不合法则提示并刷新列表
        if not my_entity or not my_entity.valid or my_portal.paired_with
           or not target_entity or not target_entity.valid or target.paired_with
           or not can_pair_entities(my_entity, target_entity) then
            player.print({"gui.portal-candidate-gone"})
            if portal_id and storage.portal_belts[portal_id] then
                show_pairing_gui(event.player_index, portal_id)
            end
            return
        end

        pair_portal_belts(portal_id, element.tags.portal_id)
        player.print({"gui.portal-paired-success"})
        player.print({"gui.portal-paired-links", gps_link(my_entity), gps_link(target_entity)})
        show_pairing_gui(event.player_index, portal_id)

    -- 解锁：解除配对，双方各自回到未配对状态，窗口刷新为候选列表态
    elseif element.name == "portal_unlock_button" then
        local player_data = storage.players[event.player_index]
        local portal_id = player_data and player_data.configuring_portal_id
        local portal = portal_id and storage.portal_belts[portal_id]
        local my_entity = portal and portal.entity
        local partner_entity = get_partner_entity(portal)

        if my_entity and my_entity.valid and partner_entity then
            local partner_portal = storage.portal_belts[portal.paired_with]
            portal.paired_with = nil
            if partner_portal then
                partner_portal.paired_with = nil
            end
            player.print({"gui.portal-unpaired", gps_link(my_entity), gps_link(partner_entity)})
            show_pairing_gui(event.player_index, portal_id)
        end

    -- 在地图上查看搭档传送带：进入以搭档为中心的远程视角（按 M 或退出按钮返回）
    elseif element.name == "portal_show_on_map_button" then
        local player_data = storage.players[event.player_index]
        local portal_id = player_data and player_data.configuring_portal_id
        local portal = portal_id and storage.portal_belts[portal_id]
        local partner = get_partner_entity(portal)
        if partner then
            player.set_controller({
                type = defines.controllers.remote,
                position = partner.position,
                surface = partner.surface
            })
        end

    -- 处理取消按钮点击
    elseif element.name == "portal_cancel_button" then
        if player.gui.center.portal_pairing_frame then
            player.gui.center.portal_pairing_frame.destroy()
        end
    end
end)

-- 执行传送检查
script.on_event(defines.events.on_tick, function(event)
    -- 每2个tick执行一次传送检查
    if event.tick % 2 ~= 0 then return end

    ensure_storage()

    -- 遍历所有空间传送实体，按类别分发
    for id, portal in pairs(storage.portal_belts) do
        local source = portal.entity
        if source and source.valid and portal.paired_with then
            local target_portal = storage.portal_belts[portal.paired_with]
            local target = target_portal and target_portal.entity

            if target and target.valid then
                if portal_kind(source) == "pipe" then
                    -- 管道无方向，双向均衡；每对只处理一次
                    if id < portal.paired_with then
                        transfer_fluids(source, target)
                    end
                else
                    -- 传送带只从输入端传送到输出端；形态实时取自实体（按 R 翻转即时生效）
                    if source.type == target.type
                       and source.belt_to_ground_type == "input"
                       and target.belt_to_ground_type == "output" then
                        transfer_items(source, target)
                    end
                end
            end
        end
    end
end)

-- 供其他 mod 或自动化测试调用的远程接口
remote.add_interface("planet-portal", {
    register = function(entity)
        if not is_portal_entity(entity) then return nil end
        return register_portal_belt(entity)
    end,
    pair = function(portal_id1, portal_id2)
        return pair_portal_belts(portal_id1, portal_id2)
    end,
    get_portals = function()
        ensure_storage()
        local result = {}
        for id, portal in pairs(storage.portal_belts) do
            local direction = nil
            if portal.entity and portal.entity.valid then
                if portal_kind(portal.entity) == "pipe" then
                    direction = "pipe"
                else
                    direction = portal.entity.belt_to_ground_type
                end
            end
            result[id] = {
                name = portal.name,
                direction = direction, -- "input"/"output"/"pipe"，实体失效时为 nil
                type = portal.type,
                paired_with = portal.paired_with,
                surface = portal.surface,
                valid = portal.entity ~= nil and portal.entity.valid
            }
        end
        return result
    end
})

-- commands
commands.add_command("list-portals", {"cmd.list-portals"}, function(command)
    ensure_storage()
    -- 玩家调用打印到聊天区；服务器控制台调用（无玩家）打印到控制台
    local player = command.player_index and game.players[command.player_index] or nil
    local function out(msg)
        if player then
            player.print(msg)
        else
            print(msg)
        end
    end

    out({"cmd.registered-portals"})

    for id, portal in pairs(storage.portal_belts) do
        local entity = portal.entity
        local valid = entity ~= nil and entity.valid

        local status = valid and {"cmd.valid"} or {"cmd.invalid"}

        local direction = {"cmd.unset"}
        if valid then
            if portal_kind(entity) == "pipe" then
                direction = {"gui.portal-pipe-kind"}
            else
                direction = (entity.belt_to_ground_type == "input")
                    and {"gui.portal-direction-in"} or {"gui.portal-direction-out"}
            end
        end

        -- 附可点击的 [gps] 链接，点击即在地图上定位该传送带（链接文本即坐标）
        local paired = portal.paired_with and {"cmd.paired"} or {"cmd.unpaired"}

        out({"cmd.log", direction, status, paired, valid and gps_link(entity) or ""})
    end
end)
